const isObj = (v) => !!v && typeof v === 'object' && !Array.isArray(v);
const str = (v) => {
  if (typeof v === 'string' && v.trim()) return v.trim();
  if (typeof v === 'number' && Number.isFinite(v)) return String(v);
  return null;
};
const first = (...vals) => {
  for (const v of vals) { const s = str(v); if (s !== null) return s; }
  return null;
};

const body = isObj($json.body) ? $json.body : $json;
const contact = [body.contact, body.data, body.payload].find(isObj) || body;
const conversation = [body.conversation, contact.conversation].find(isObj) || {};
const assignee = [body.assignee, body.user, contact.assignee].find(isObj) || {};

const contactId = first(
  contact.id, contact.contact_id, contact.contactId,
  body.contact_id, body.contactId
);
if (!contactId) {
  throw new Error('No Respond.io contact id in payload: ' + JSON.stringify(body).slice(0, 500));
}

const contactName = first(
  contact.name, contact.full_name, contact.fullName,
  [str(contact.firstName || contact.first_name), str(contact.lastName || contact.last_name)]
    .filter(Boolean).join(' ')
);

// Respond.io does not always send an event id. When it does not, SIMS builds its
// idempotency key from event type + contact + timestamp + conversation instead, so a
// stable timestamp matters more than a pretty one. Duplicate tickets are additionally
// blocked server-side by the open-ticket guard in handleContactTagUpdated.
const eventId = first(body.event_id, body.eventId, body.id);
const occurredAt = first(body.occurred_at, body.occurredAt, body.timestamp, body.created_at, body.updated_at)
  || new Date().toISOString();

const base = {
  event_id: eventId,
  occurred_at: occurredAt,
  contact: {
    id: contactId,
    name: contactName,
    email: first(contact.email, contact.contact_email),
    phone: first(contact.phone, contact.phone_number, contact.phoneNumber),
  },
  conversation: {
    conversation_id: first(conversation.id, conversation.conversation_id, body.conversation_id, body.conversationId),
  },
};

return { json: { ...base, event_type: 'conversation.closed' } };
